mapper.select:
WITH FILTERED_MST AS( SELECT a.real_stock_mst_id ,a.real_stock_date ,a.item_type_cd ,a.storage_cd ,a.area_cd ,a.manager_id ,a.end_yn FROM tb_real_stock_mst a WHERE a.real_stock_date BETWEEN #{strDate} AND #{endDate}
AND a.item_type_cd = #{itemTypeCd}
AND a.area_cd = #{areaCd}
AND a.storage_cd = #{storageCd}
), ITEM_AGG AS ( SELECT b.real_stock_mst_id ,COUNT(*) AS item_count ,MIN(b.item_cd) AS first_item_cd ,SUM(ISNULL(b.doc_stock_qty, 0)) AS doc_stock_qty ,SUM(ISNULL(b.reql_stock_qty, 0)) AS reql_stock_qty FROM tb_real_stock_item b INNER JOIN FILTERED_MST a ON a.real_stock_mst_id = b.real_stock_mst_id
INNER JOIN tb_item_mst i ON i.item_cd = b.item_cd
WHERE 1 = 1
AND b.item_cd LIKE CONCAT( '%', dbo.fn_LikeEscape(#{itemCd}), '%' )
AND i.item_name LIKE CONCAT( '%', dbo.fn_LikeEscape(#{itemName}), '%' )
GROUP BY b.real_stock_mst_id ) SELECT a.real_stock_mst_id ,a.real_stock_date ,c.code_nm AS item_type_name ,CASE WHEN ISNULL(s.item_count, 0) = 0 THEN '' WHEN s.item_count = 1 THEN ISNULL(i.item_name, '') ELSE CONCAT( ISNULL(i.item_name, ''), ' 외 ', s.item_count - 1, '건' ) END AS item_name ,dbo.getStorageName(a.storage_cd) AS storage_name ,u.member_nm AS manager_name ,c1.code_nm AS area_name ,ISNULL(s.doc_stock_qty, 0) AS doc_stock_qty ,ISNULL(s.reql_stock_qty, 0) AS reql_stock_qty ,ISNULL(s.reql_stock_qty, 0) - ISNULL(s.doc_stock_qty, 0) AS diffStockQty ,a.end_yn FROM FILTERED_MST a LEFT JOIN ITEM_AGG s ON s.real_stock_mst_id = a.real_stock_mst_id LEFT JOIN tb_item_mst i ON i.item_cd = s.first_item_cd LEFT JOIN tb_common_code c ON c.code = a.item_type_cd AND c.com_type_cd = 'item_type_cd' LEFT JOIN tb_common_code c1 ON c1.code = a.area_cd AND c1.com_type_cd = 'area' LEFT JOIN tb_users u ON u.user_id = a.manager_id WHERE 1 = 1
AND s.real_stock_mst_id IS NOT NULL
ORDER BY a.real_stock_date DESC ,a.real_stock_mst_id DESC

select  item_cd
       ,item_name
       ,test_no
       ,storage_cd
       ,qty docStockQty
       ,0 as reqlStockQty
       ,'' etc
from   dbo.fn_get_stock(
               COALESCE(TRY_CAST(NULLIF(CAST(NULL AS NVARCHAR(20)), '') AS DATE), CAST(GETDATE() AS DATE)
               )    -- 재고 기준일
           ,#{areaCd}
           ,#{storageCd}
           ,#{itemTypeCd}
           ,#{itemCd}
           ,#{itemName}
           ,'TEST'
           ,NULL
       ) s

mapper.update:
update tb_real_stock_item
set    reql_stock_qty = #{reqlStockQty}
      ,etc            = #{etc}
      ,upd_id         = #{userId}
      ,upd_dt         = getDate()
where  real_stock_item_id = #{realStockItemId}

update tb_real_stock_mst
set    tran_id = #{tranId}
      ,end_yn  = 'Y'
      ,upd_id  = #{userId}
      ,upd_dt  = getDate()
where  real_stock_mst_id = #{realStockMstId}
